);font-size:11px}.sg-wallet-withdrawal-row>div:last-child{display:grid;justify-items:end;align-content:start;gap:6px}.sg-wallet-withdrawal-row em{background:#fff4de;color:#9a6400}.sg-wallet-withdrawal-row em.is-paid{background:var(--sg3-green-soft);color:var(--sg3-green-dark)}.sg-wallet-withdrawal-row em.is-rejected{background:#fff0f0;color:#b42318}.sg-wallet-withdrawal-row button{padding:0;border:0;background:transparent;color:#b42318;cursor:pointer;font-size:11px}.sg-wallet-withdrawal-row p{grid-column:1/-1;margin:0;color:#b42318;font-size:11px}.sg-wallet-help{display:flex;gap:10px;margin-top:13px;padding:15px;color:var(--sg3-green-dark)}.sg-wallet-help p{margin:5px 0 0;color:var(--sg3-muted);font-size:12px;line-height:1.5}.sg-wallet-modal-backdrop{position:fixed;z-index:1000;inset:0;display:grid;place-items:center;padding:18px;background:rgba(10,28,17,.4)}.sg-wallet-modal{width:min(520px,100%);max-height:calc(100vh - 36px);overflow:auto;border:1px solid var(--sg3-line);border-radius:16px;background:#fff;box-shadow:0 22px 60px rgba(12,37,22,.2)}.sg-wallet-modal>header{display:flex;align-items:start;justify-content:space-between;gap:15px;padding:20px;border-bottom:1px solid var(--sg3-line)}.sg-wallet-modal>header h2{margin:0;font-size:20px}.sg-wallet-modal>header button{display:grid;width:32px;height:32px;place-items:center;border:1px solid var(--sg3-line);border-radius:8px;background:#fff;color:var(--sg3-muted);cursor:pointer}.sg-wallet-modal-body{display:grid;gap:14px;padding:19px}.sg-wallet-modal-balance{display:grid;gap:4px;padding:13px;border-radius:10px;background:var(--sg3-green-soft)}.sg-wallet-modal-balance span{color:var(--sg3-muted);font-size:11px}.sg-wallet-modal-balance strong{color:var(--sg3-green-dark);font-size:22px}.sg-wallet-modal .sg3-field{display:grid;gap:6px}.sg-wallet-modal .sg3-field>span{color:var(--sg3-muted);font-size:11px;font-weight:800}.sg-wallet-modal input,.sg-wallet-modal select{box-sizing:border-box;width:100%;min-height:42px;padding:0 11px;border:1px solid var(--sg3-line-strong);border-radius:8px;background:#fff;color:var(--sg3-ink)}.sg-wallet-modal .sg3-field small{color:var(--sg3-muted);font-size:11px}.sg-wallet-modal-fields{display:grid;grid-template-columns:1fr 1fr;gap:11px}.sg-wallet-check{display:flex;align-items:center;gap:8px;color:var(--sg3-ink);font-size:12px}.sg-wallet-check input{accent-color:var(--sg3-green)}.sg-wallet-modal-note,.sg-wallet-action-error{margin:0;color:#b42318;font-size:12px}.sg-wallet-modal>footer,.sg-wallet-modal-body>footer{display:flex;justify-content:flex-end;gap:8px;padding:15px 19px;border-top:1px solid var(--sg3-line)}.sg-wallet-existing-accounts{display:grid;gap:7px;padding:0 19px 19px}.sg-wallet-existing-accounts button{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px;border:1px solid var(--sg3-line);border-radius:9px;background:#fbfefc;text-align:left;cursor:pointer}.sg-wallet-existing-accounts button span{display:grid;gap:3px}.sg-wallet-existing-accounts small{color:var(--sg3-muted);font-size:11px}@media(max-width:950px){.sg-wallet-content-grid{grid-template-columns:1fr}.sg-wallet-balance-card{grid-template-columns:1fr}.sg-wallet-balance-side{padding:13px 0 0;border-top:1px solid rgba(255,255,255,.2);border-left:0}}@media(max-width:650px){.sg-wallet-head-actions{width:100%}.sg-wallet-head-actions .sg3-button{flex:1}.sg-wallet-insight-grid{grid-template-columns:1fr}.sg-wallet-table-head{display:none}.sg-wallet-ledger-table article{grid-template-columns:minmax(0,1fr) auto;gap:8px}.sg-wallet-ledger-table article>span{grid-column:1/-1;text-align:left}.sg-wallet-modal-fields{grid-template-columns:1fr}}
